import re
def nums(s):
 if not s:return None
 o=[]
 for z in s.split(','):
  if not re.fullmatch(r'0|-?[1-9][0-9]*',z):return None
  x=int(z)
  if x < -1000 or x > 1000:return None
  o.append(x)
 return o
def consecutive_run_summary(s: str) -> str | None:
 a=nums(s)
 if a is None:return None
 o=[]
 for x in a:
  if o and o[-1][0]==x:o[-1][1]+=1
  else:o.append([x,1])
 return ','.join(f'{x}:{n}' for x,n in o)
